using System;
using System.Collections.Generic;
using System.Linq;

namespace LinqDemo
{
    public class Student
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public int Age { get; set; }
        public string City { get; set; }
        public List<int> Scores { get; set; }
    }

    class Program
    {
        static void Main()
        {
            var students = new List<Student>
            {
                new Student { Id = 1, Name = "Alice", Age = 20, City = "Beijing", Scores = new List<int> { 85, 90, 78 } },
                new Student { Id = 2, Name = "Bob", Age = 22, City = "Shanghai", Scores = new List<int> { 92, 88, 95 } },
                new Student { Id = 3, Name = "Charlie", Age = 19, City = "Beijing", Scores = new List<int> { 76, 82, 80 } },
                new Student { Id = 4, Name = "David", Age = 21, City = "Guangzhou", Scores = new List<int> { 90, 85, 88 } },
                new Student { Id = 5, Name = "Eve", Age = 23, City = "Shanghai", Scores = new List<int> { 95, 92, 98 } }
            };

            // 查询语法 - 过滤和排序
            var query1 = from s in students
                         where s.Age >= 20
                         orderby s.Name
                         select s;

            // 方法语法 - 投影
            var query2 = students
                .Where(s => s.Age >= 20)
                .OrderBy(s => s.Name)
                .Select(s => new { s.Name, s.Age, AverageScore = s.Scores.Average() });

            // 分组操作
            var groupedByCity = students
                .GroupBy(s => s.City)
                .Select(g => new
                {
                    City = g.Key,
                    Count = g.Count(),
                    Students = g.ToList()
                });

            // SelectMany - 展开嵌套集合
            var allScores = students
                .SelectMany(s => s.Scores)
                .OrderByDescending(score => score);

            // 聚合操作
            var statistics = new
            {
                TotalStudents = students.Count(),
                AverageAge = students.Average(s => s.Age),
                MaxScore = students.SelectMany(s => s.Scores).Max(),
                MinAge = students.Min(s => s.Age)
            };

            // 延迟执行演示
            Console.WriteLine("=== 延迟执行演示 ===");
            var deferredQuery = students.Where(s =>
            {
                Console.WriteLine($"Checking {s.Name}");
                return s.Age > 20;
            });

            Console.WriteLine("Query created, not executed yet.");
            Console.WriteLine("Now iterating...");
            foreach (var s in deferredQuery)
            {
                Console.WriteLine($"Result: {s.Name}");
            }

            // 立即执行
            Console.WriteLine("\n=== 立即执行 ===");
            var immediateList = students
                .Where(s => s.Age > 20)
                .ToList(); // 立即执行并缓存

            // 链式调用构建复杂查询
            Console.WriteLine("\n=== 复杂查询 ===");
            var complexQuery = students
                .Where(s => s.City == "Shanghai")
                .OrderByDescending(s => s.Scores.Average())
                .Take(2)
                .Select(s => new
                {
                    s.Name,
                    s.Age,
                    TopScore = s.Scores.Max(),
                    Average = s.Scores.Average()
                });

            foreach (var item in complexQuery)
            {
                Console.WriteLine($"{item.Name}: Age={item.Age}, Top={item.TopScore}, Avg={item.Average:F1}");
            }

            // Contains 和 Any
            Console.WriteLine("\n=== 集合操作 ===");
            var cities = new[] { "Beijing", "Shanghai" };
            var studentsInCities = students.Where(s => cities.Contains(s.City));
            var hasAdult = students.Any(s => s.Age >= 18);
        }
    }
}
